const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];

function showScreen(name) {
  $$('.screen').forEach((screen) => screen.classList.toggle('active', screen.id === `${name}-screen`));
  const pianoCard = $('#piano-experience-card');
  if (pianoCard && name === 'games') pianoCard.setAttribute('aria-expanded', 'false');
  const fidgetCard = $('#fidget-experience-card');
  if (fidgetCard && name === 'games') fidgetCard.setAttribute('aria-expanded', 'false');
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

document.addEventListener('click', (event) => {
  const screenButton = event.target.closest('[data-screen]');
  if (screenButton) showScreen(screenButton.dataset.screen);
  const gameButton = event.target.closest('[data-game]');
  if (gameButton) showScreen(gameButton.dataset.game);
});

