async function loadPianoSample(sampleMidi){if(pianoBuffers.has(sampleMidi))return pianoBuffers.get(sampleMidi);if(pianoLoads.has(sampleMidi))return pianoLoads.get(sampleMidi);pianoContext??=new (window.AudioContext||window.webkitAudioContext)();const load=fetch(pianoSampleUrls[sampleMidi]).then((response)=>{if(!response.ok)throw new Error('Piano sample failed to load');return response.arrayBuffer()}).then((data)=>pianoContext.decodeAudioData(data)).then((buffer)=>{pianoBuffers.set(sampleMidi,buffer);return buffer});pianoLoads.set(sampleMidi,load);return load}
