async function playPianoKey(midi){if(!pianoContext)pianoContext=new (window.AudioContext||window.webkitAudioContext)();await pianoContext.resume();const sampleMidi=nearestPianoSample(midi);const status=$('#piano-status');if(status)status.textContent='Loading recorded piano…';try{const buffer=await loadPianoSample(sampleMidi);const source=pianoContext.createBufferSource();const gain=pianoContext.createGain();source.buffer=buffer;source.playbackRate.value=2**((midi-sampleMidi)/12);gain.gain.setValueAtTime(.72, pianoContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,pianoContext.currentTime+3.8);source.connect(gain).connect(pianoOutput||pianoContext.destination);source.start();if(status)status.textContent=`${pianoKeyNames[midi%12]}${Math.floor(midi/12)-1} · recorded piano sample`}catch(error){if(status)status.textContent='Piano sample unavailable. Check your connection.'}}
