// Tic Tac Toe
let tttBoard = Array(9).fill(''); let tttTurn = 'X'; let tttMode = 'bot'; let tttOver = false; let tttScores = { X: 0, O: 0 };
const wins = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
function tttWinner(board) { return wins.find(([a,b,c]) => board[a] && board[a] === board[b] && board[a] === board[c]); }
function renderTtt() { $('#ttt-board').innerHTML = tttBoard.map((value, index) => `<button class="ttt-cell ${value === 'O' ? 'o' : ''}" role="gridcell" aria-label="Cell ${index + 1}" ${value || tttOver || (tttMode === 'bot' && tttTurn === 'O') ? 'disabled' : ''} data-ttt-cell="${index}">${value}</button>`).join(''); $('#ttt-you-score').textContent = tttScores.X; $('#ttt-opponent-score').textContent = tttScores.O; $('#ttt-opponent-label').textContent = tttMode === 'bot' ? 'BOT' : 'FRIEND'; }
function finishTtt(winner) { tttOver = true; if (winner) { tttScores[winner[0]]++; const winnerName=tttMode==='bot'?(winner[0]==='X'?'YOU':'BOT'):(winner[0]==='X'?'PLAYER 1':'PLAYER 2'); awardPartyPoints(winnerName,5); $('#ttt-message').textContent = winner[0] === 'X' ? 'You got three in a row! 🎉' : `${tttMode === 'bot' ? 'The bot' : 'Player 2'} wins this round.`; } else $('#ttt-message').textContent = 'A draw! Great defense from both sides.'; renderTtt(); }
function botMove() { if (tttOver) return; const open = tttBoard.map((v,i) => v ? null : i).filter((v) => v !== null); let choice = open.find((i) => { const next = [...tttBoard]; next[i] = 'O'; return tttWinner(next); }); if (choice === undefined) choice = open.find((i) => { const next = [...tttBoard]; next[i] = 'X'; return tttWinner(next); }); if (choice === undefined && open.includes(4)) choice = 4; if (choice === undefined) choice = open[Math.floor(Math.random() * open.length)]; if (choice !== undefined) playTtt(choice, 'O'); }
function playTtt(index, player = 'X') { if (tttBoard[index] || tttOver) return; tttBoard[index] = player; const winner = tttWinner(tttBoard); if (winner || tttBoard.every(Boolean)) return finishTtt(winner); tttTurn = player === 'X' ? 'O' : 'X'; $('#ttt-turn').innerHTML = tttTurn === 'X' ? 'YOUR TURN <b>●</b>' : (tttMode === 'bot' ? 'BOT IS THINKING…' : "PLAYER 2'S TURN"); renderTtt(); if (tttMode === 'bot' && tttTurn === 'O') setTimeout(botMove, 400); }
function resetTtt() { tttBoard = Array(9).fill(''); tttTurn = 'X'; tttOver = false; $('#ttt-turn').innerHTML = 'YOUR TURN <b>●</b>'; $('#ttt-message').textContent = 'Place your X to start!'; renderTtt(); }
$('#ttt-board').addEventListener('click', (event) => { const cell = event.target.closest('[data-ttt-cell]'); if (cell) playTtt(Number(cell.dataset.tttCell), tttTurn); });
$$('[data-mode]').forEach((button) => button.addEventListener('click', () => { tttMode = button.dataset.mode; $$('[data-mode]').forEach((b) => b.classList.toggle('active', b === button)); resetTtt(); }));
