let dotsLines = { h: [], v: [] }; let dotsBoxes = Array(9).fill(''); let dotsPlayer = 1; let dotsScores = [0, 0]; let dotsFinished = false; let dotsMode = 'bot'; let dotsBotThinking = false; let dotsNames = ['PLAYER 1', 'BOT'];
const dotsBotThinkingCard=document.createElement('div'); dotsBotThinkingCard.id='dots-bot-thinking'; dotsBotThinkingCard.className='bot-thinking'; dotsBotThinkingCard.innerHTML='<span class="bot-face" aria-hidden="true"></span><b>BOT THINKING</b><i class="thinking-dots">•••</i>'; dotsBotThinkingCard.setAttribute('aria-hidden','true'); $('#dots-screen .dots-panel').appendChild(dotsBotThinkingCard);
