function renderDots() { const board = $('#dots-board'); let html = ''; dotsBoxes.forEach((v,i) => { if(v) html += `<span class="dot-box p${v}" style="top:${Math.floor(i/3)*33.333 + 4}%;left:${(i%3)*33.333 + 4}%"></span>`; }); for (let r=0;r<4;r++) for(let c=0;c<3;c++) { const i=r*3+c; const owner=dotsLines.h[i]; html += `<button class="dots-line h ${owner ? `placed-line claimed-p${owner}` : ''}" style="top:${r*33.333}%;left:${c*33.333}%" data-line="h-${i}" ${dotsBotThinking ? 'disabled' : ''} aria-label="Horizontal line ${i+1}"></button>`; } for (let r=0;r<3;r++) for(let c=0;c<4;c++) { const i=r*4+c; const owner=dotsLines.v[i]; html += `<button class="dots-line v ${owner ? `placed-line claimed-p${owner}` : ''}" style="top:${r*33.333}%;left:${c*33.333}%" data-line="v-${i}" ${dotsBotThinking ? 'disabled' : ''} aria-label="Vertical line ${i+1}"></button>`; } for (let r=0;r<4;r++) for(let c=0;c<4;c++) html += `<span class="dot-point" style="top:${r*33.333}%;left:${c*33.333}%"></span>`; board.innerHTML=html; $('#dots-p1-label').textContent=dotsNames[0]; $('#dots-p2-label').textContent=dotsNames[1]; $('#dots-p1-score').textContent=dotsScores[0]; $('#dots-p2-score').textContent=dotsScores[1]; $('#dots-turn').textContent=dotsFinished ? 'ROUND COMPLETE' : dotsBotThinking ? `${dotsNames[1]} IS THINKING…` : `${dotsNames[dotsPlayer - 1]}'S TURN`; }
function lineCreatesBox(kind,index) { const boxes=[]; if(kind==='h'){const r=Math.floor(index/3),c=index%3;if(r>0)boxes.push((r-1)*3+c);if(r<3)boxes.push(r*3+c)} else {const r=Math.floor(index/4),c=index%4;if(c>0)boxes.push(r*3+c-1);if(c<3)boxes.push(r*3+c)} return boxes.filter(i=>!dotsBoxes[i] && ((dotsLines.h[i]??false) && (dotsLines.h[i+3]??false) && (dotsLines.v[rIndex(i)]??false) && (dotsLines.v[rIndex(i)+1]??false)) || false); }
function rIndex(i){return Math.floor(i/3)*4+i%3}
function clickDotLine(kind,index){if(dotsFinished||dotsBotThinking||dotsLines[kind][index])return;dotsLines[kind][index]=dotsPlayer;let gained=0;const r=kind==='h'?Math.floor(index/3):Math.floor(index/4),c=kind==='h'?index%3:index%4;const candidates=kind==='h'?[...(r>0?[ (r-1)*3+c]:[]),...(r<3?[r*3+c]:[])]:[...(c>0?[r*3+c-1]:[]),...(c<3?[r*3+c]:[])];candidates.forEach(i=>{const row=Math.floor(i/3),col=i%3;const complete=dotsLines.h[row*3+col]&&dotsLines.h[(row+1)*3+col]&&dotsLines.v[row*4+col]&&dotsLines.v[row*4+col+1];if(complete&&!dotsBoxes[i]){dotsBoxes[i]=dotsPlayer;dotsScores[dotsPlayer-1]++;gained++}});if(!gained)dotsPlayer=dotsPlayer===1?2:1;if(dotsBoxes.every(Boolean)){dotsFinished=true;const tied=dotsScores[0]===dotsScores[1];if(!tied){const winnerIndex=dotsScores[0]>dotsScores[1]?0:1;awardPartyPoints(dotsMode==='bot'?(winnerIndex===0?'YOU':'BOT'):dotsNames[winnerIndex],8)}$('#dots-message').textContent=tied?'It’s a tie!':`${dotsNames[dotsScores[0]>dotsScores[1]?0:1]} wins the board!`;}else $('#dots-message').textContent=gained?`${dotsNames[dotsPlayer-1]} gets another turn.`:`${dotsNames[dotsPlayer-1]}, pick a line.`;renderDots();if(dotsMode==='bot'&&dotsPlayer===2&&!dotsFinished){dotsBotThinking=true;renderDots();syncDotsBotThinking();setTimeout(dotsBotMove,ownedShopItems.has('slow-bot')?1500:800)}}
function dotsMoveScoresBox(kind,index){const before=dotsLines[kind][index];dotsLines[kind][index]=dotsPlayer;const r=kind==='h'?Math.floor(index/3):Math.floor(index/4),c=kind==='h'?index%3:index%4;const candidates=kind==='h'?[...(r>0?[(r-1)*3+c]:[]),...(r<3?[r*3+c]:[])]:[...(c>0?[r*3+c-1]:[]),...(c<3?[r*3+c]:[])];const score=candidates.filter((i)=>{const row=Math.floor(i/3),col=i%3;return !dotsBoxes[i]&&dotsLines.h[row*3+col]&&dotsLines.h[(row+1)*3+col]&&dotsLines.v[row*4+col]&&dotsLines.v[row*4+col+1]}).length;dotsLines[kind][index]=before;return score}
function dotsBotMove(){if(dotsFinished||dotsMode!=='bot'||dotsPlayer!==2)return;const openH=dotsLines.h.map((v,i)=>v?null:`h-${i}`).filter(Boolean);const openV=dotsLines.v.map((v,i)=>v?null:`v-${i}`).filter(Boolean);const open=[...openH,...openV];if(!open.length)return;const scoring=ownedShopItems.has('smart-bot')?open.filter((token)=>{const [kind,index]=token.split('-');return dotsMoveScoresBox(kind,Number(index))>0}):[];const pool=scoring.length?scoring:open;const choice=pool[Math.floor(Math.random()*pool.length)].split('-');dotsBotThinking=false;syncDotsBotThinking();clickDotLine(choice[0],Number(choice[1]))}
